route.example:
kcds.core.Http.route('GET', '/status', () => {
  return { status: 200, body: { players: kcds.players.Player.all().length } };
});

route.exampleLua:
kcds.core.Http.route("GET", "/status", function()
  return { status = 200, body = { players = #kcds.players.Player.all() } }
end)

route.exampleCs:
Http.Route("GET", "/status", object? () =>
{
    return new { status = 200, body = new { players = Player.All().Length } };
});

enabled.example:
if (!kcds.core.Http.enabled) {
  console.warn('set KCDS_HTTP_PORT to serve the shop API');
}

enabled.exampleCs:
if (!Http.Enabled)
{
